pub fn first_in_sorted(arr: &[i64], x: i64) -> i64 {
    let (mut lo, mut hi) = (0usize, arr.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo < arr.len() && arr[lo] == x {
        lo as i64
    } else {
        -1
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(first_in_sorted(&[3, 4, 5, 5, 5, 5, 6], 5), 2);
        assert_eq!(first_in_sorted(&[1, 2], 7), -1);
        assert_eq!(first_in_sorted(&[], 7), -1);
    }

    proptest! {
        #[test]
        fn matches_linear(mut v in proptest::collection::vec(-5i64..5, 0..30), x in -6i64..6) {
            v.sort();
            let exp = v.iter().position(|&y| y == x).map(|i| i as i64).unwrap_or(-1);
            prop_assert_eq!(first_in_sorted(&v, x), exp);
        }
    }
}

pub fn kth_smallest(arr: &[i64], k: usize) -> i64 {
    let mut v = arr.to_vec();
    v.sort();
    v[k]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn examples() {
        assert_eq!(kth_smallest(&[7, 1, 7, 3], 0), 1);
        assert_eq!(kth_smallest(&[7, 1, 7, 3], 2), 7);
        assert_eq!(kth_smallest(&[7, 1, 7, 3], 3), 7);
        assert_eq!(kth_smallest(&[i64::MIN, i64::MAX], 1), i64::MAX);
    }
}

pub fn lis_length(arr: &[i64]) -> usize {
    let mut tails: Vec<i64> = Vec::new();
    for &x in arr {
        let pos = tails.partition_point(|&t| t < x);
        if pos == tails.len() {
            tails.push(x);
        } else {
            tails[pos] = x;
        }
    }
    tails.len()
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn brute(arr: &[i64]) -> usize {
        let mut dp = vec![1usize; arr.len()];
        let mut best = 0;
        for i in 0..arr.len() {
            for j in 0..i {
                if arr[j] < arr[i] {
                    dp[i] = dp[i].max(dp[j] + 1);
                }
            }
            best = best.max(dp[i]);
        }
        best
    }

    #[test]
    fn examples() {
        assert_eq!(lis_length(&[4, 1, 5, 3, 7, 6, 2]), 3);
        assert_eq!(lis_length(&[2, 2, 2]), 1);
        assert_eq!(lis_length(&[]), 0);
        assert_eq!(lis_length(&[i64::MIN, i64::MAX]), 2);
    }

    proptest! {
        #[test]
        fn matches_brute(arr in proptest::collection::vec(-10i64..10, 0..100)) {
            prop_assert_eq!(lis_length(&arr), brute(&arr));
        }
    }
}

pub fn next_permutation(a: &mut [i64]) -> bool {
    let n = a.len();
    if n < 2 {
        return false;
    }
    let mut i = n - 1;
    while i > 0 && a[i - 1] >= a[i] {
        i -= 1;
    }
    if i == 0 {
        a.reverse();
        return false;
    }
    let mut j = n - 1;
    while a[j] <= a[i - 1] {
        j -= 1;
    }
    a.swap(i - 1, j);
    a[i..].reverse();
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn examples() {
        let mut a = [3, 2, 4, 1];
        assert!(next_permutation(&mut a));
        assert_eq!(a, [3, 4, 1, 2]);
        let mut b = [3, 2, 1];
        assert!(!next_permutation(&mut b));
        assert_eq!(b, [1, 2, 3]);
        let mut c = [1, 1, 2];
        assert!(next_permutation(&mut c));
        assert_eq!(c, [1, 2, 1]);
        let mut e: [i64; 0] = [];
        assert!(!next_permutation(&mut e));
    }

    #[test]
    fn enumerates_multiset() {
        let mut a = [1, 1, 2, 2, 3];
        let mut count = 1;
        while next_permutation(&mut a) {
            count += 1;
        }
        assert_eq!(count, 30);
        assert_eq!(a, [1, 1, 2, 2, 3]);
    }
}

pub fn count_change(coins: &[i64], total: i64) -> u64 {
    if total < 0 {
        return 0;
    }
    let t = total as usize;
    let mut dp = vec![0u64; t + 1];
    dp[0] = 1;
    for &c in coins {
        if c <= 0 {
            continue;
        }
        let c = c as usize;
        for i in c..=t {
            dp[i] = dp[i].wrapping_add(dp[i - c]);
        }
    }
    dp[t]
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn examples() {
        assert_eq!(count_change(&[1, 5, 10, 25], 11), 4);
        assert_eq!(count_change(&[2], 3), 0);
        assert_eq!(count_change(&[], 0), 1);
        assert_eq!(count_change(&[], 5), 0);
    }
}

pub fn knapsack(capacity: usize, weights: &[i64], values: &[i64]) -> i64 {
    let mut dp = vec![0i64; capacity + 1];
    for (&w, &v) in weights.iter().zip(values.iter()) {
        if w < 0 || w as u64 > capacity as u64 {
            continue;
        }
        let w = w as usize;
        for c in (w..=capacity).rev() {
            let cand = dp[c - w] + v;
            if cand > dp[c] {
                dp[c] = cand;
            }
        }
    }
    dp[capacity]
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn examples() {
        assert_eq!(knapsack(100, &[60, 50, 20, 20, 8, 3], &[10, 8, 4, 4, 3, 2]), 19);
        assert_eq!(knapsack(5, &[5], &[7]), 7);
        assert_eq!(knapsack(4, &[5], &[7]), 0);
        assert_eq!(knapsack(0, &[], &[]), 0);
    }
}

pub fn edit_distance(a: &[i64], b: &[i64]) -> usize {
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for i in 1..=a.len() {
        let mut cur = vec![0usize; b.len() + 1];
        cur[0] = i;
        for j in 1..=b.len() {
            let sub = prev[j - 1] + usize::from(a[i - 1] != b[j - 1]);
            cur[j] = sub.min(prev[j] + 1).min(cur[j - 1] + 1);
        }
        prev = cur;
    }
    prev[b.len()]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn examples() {
        assert_eq!(edit_distance(&[1, 2, 3], &[1, 3]), 1);
        assert_eq!(edit_distance(&[5, 6], &[7, 8]), 2);
        assert_eq!(edit_distance(&[], &[4, 4]), 2);
        assert_eq!(edit_distance(&[], &[]), 0);
    }
}

pub fn common_substring(a: &[i64], b: &[i64]) -> usize {
    let mut prev = vec![0usize; b.len() + 1];
    let mut best = 0;
    for i in 0..a.len() {
        let mut cur = vec![0usize; b.len() + 1];
        for j in 0..b.len() {
            if a[i] == b[j] {
                cur[j + 1] = prev[j] + 1;
                best = best.max(cur[j + 1]);
            }
        }
        prev = cur;
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn examples() {
        assert_eq!(common_substring(&[1, 2, 3, 4], &[9, 2, 3, 9]), 2);
        assert_eq!(common_substring(&[1, 2], &[3]), 0);
        assert_eq!(common_substring(&[], &[3]), 0);
    }
}

pub fn count_primes(n: u64) -> u64 {
    let n = n as usize;
    if n < 2 {
        return 0;
    }
    let mut sieve = vec![true; n + 1];
    sieve[0] = false;
    sieve[1] = false;
    let mut i = 2;
    while i * i <= n {
        if sieve[i] {
            let mut j = i * i;
            while j <= n {
                sieve[j] = false;
                j += i;
            }
        }
        i += 1;
    }
    sieve.iter().filter(|&&b| b).count() as u64
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert_eq!(count_primes(0), 0);
        assert_eq!(count_primes(1), 0);
        assert_eq!(count_primes(2), 1);
        assert_eq!(count_primes(10), 4);
        assert_eq!(count_primes(100), 25);
        assert_eq!(count_primes(20000), 2262);
    }
}

pub fn counting_sort(a: &mut [i64], k: i64) {
    let k = if k < 1 { 1 } else { k } as usize;
    let mut counts = vec![0usize; k];
    for &x in a.iter() {
        counts[x as usize] += 1;
    }
    let mut i = 0;
    for (v, &c) in counts.iter().enumerate() {
        for _ in 0..c {
            a[i] = v as i64;
            i += 1;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn sorts(k in 1i64..=64, v in proptest::collection::vec(0i64..64, 0..1000)) {
            let mut a: Vec<i64> = v.into_iter().map(|x| x % k).collect();
            let mut e = a.clone();
            e.sort();
            counting_sort(&mut a, k);
            prop_assert_eq!(a, e);
        }
    }
}

pub fn balanced(p: &[i64]) -> bool {
    let mut d: i64 = 0;
    for &x in p {
        d += x;
        if d < 0 {
            return false;
        }
    }
    d == 0
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert!(balanced(&[1, 1, -1, -1]));
        assert!(!balanced(&[-1, 1]));
        assert!(!balanced(&[1]));
        assert!(balanced(&[]));
    }
}

pub fn binomial(n: u64, k: u64) -> u64 {
    if k > n {
        return 0;
    }
    let k = k.min(n - k) as usize;
    // Pascal row up to column k; all entries fit in u64 for n <= 67.
    let mut row = vec![0u64; k + 1];
    row[0] = 1;
    for i in 1..=n as usize {
        let top = i.min(k);
        for j in (1..=top).rev() {
            row[j] += row[j - 1];
        }
    }
    row[k]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn examples() {
        assert_eq!(binomial(5, 2), 10);
        assert_eq!(binomial(4, 0), 1);
        assert_eq!(binomial(3, 4), 0);
        assert_eq!(binomial(0, 0), 1);
        assert_eq!(binomial(67, 33), 14226520737620288370);
        assert_eq!(binomial(67, u64::MAX), 0);
        for n in 0..=67u64 {
            for k in 0..=n + 2 {
                if k <= n && k > 0 && n > 0 && k < n {
                    assert_eq!(binomial(n, k), binomial(n - 1, k - 1) + binomial(n - 1, k));
                }
            }
        }
    }
}
